// Extractor HTML Versión Final - Estructura simplificada
// Para usar en nodo Code de n8n

const htmlContent = $input.all()[0].json.data || '';

// Función para limpiar atributos de estilo pero preservar contenido HTML
const limpiarElemento = (html) => {
  if (!html) return '';

  return html
    // Remover atributos de presentación específicos
    .replace(/\s+(style|class|border|cellpadding|cellspacing|width|height|bgcolor|align|valign|font-size|font-family|color)\s*=\s*["'][^"']*["']/gi, '')
    // Limpiar espacios extra entre tags
    .replace(/\s+>/g, '>')
    .replace(/>\s+</g, '><')
    .trim();
};

const resultado = {
  variables: {},
  tablas: [],
  debug: []
};

try {
  // Buscar el div#variables - método más robusto
  const variablesStart = htmlContent.search(/<div[^>]*id\s*=\s*["']variables["'][^>]*>/i);

  if (variablesStart === -1) {
    resultado.debug.push('No se encontró div#variables');
    return [{ json: { error: 'No se encontró div#variables', ...resultado } }];
  }

  // Encontrar el tag de apertura completo
  const openTagMatch = htmlContent.substring(variablesStart).match(/^<div[^>]*>/i);
  if (!openTagMatch) {
    resultado.debug.push('Error procesando tag de apertura de variables');
    return [{ json: { error: 'Error procesando tag de apertura', ...resultado } }];
  }

  const contentStart = variablesStart + openTagMatch[0].length;

  // Buscar el cierre correspondiente contando divs anidados
  let depth = 1;
  let pos = contentStart;
  let variablesEnd = -1;

  while (depth > 0 && pos < htmlContent.length) {
    const nextDivOpen = htmlContent.indexOf('<div', pos);
    const nextDivClose = htmlContent.indexOf('</div>', pos);

    if (nextDivClose === -1) break;

    if (nextDivOpen !== -1 && nextDivOpen < nextDivClose) {
      depth++;
      pos = nextDivOpen + 4;
    } else {
      depth--;
      if (depth === 0) {
        variablesEnd = nextDivClose;
      }
      pos = nextDivClose + 6;
    }
  }

  if (variablesEnd === -1) {
    resultado.debug.push('No se encontró cierre de div#variables');
    return [{ json: { error: 'No se encontró cierre de div#variables', ...resultado } }];
  }

  const variablesContent = htmlContent.substring(contentStart, variablesEnd);
  resultado.debug.push(`Contenido variables encontrado: ${variablesContent.length} caracteres`);

  // Buscar todos los divs con atributo variable dentro de #variables
  const variableRegex = /<div\s+variable\s*=\s*["']([^"']+)["']([^>]*)>([\s\S]*?)<\/div>/gi;
  let match;

  while ((match = variableRegex.exec(variablesContent)) !== null) {
    const varName = match[1];           // nombre de la variable
    const attributes = match[2];        // otros atributos del div
    const varContent = match[3];        // contenido del div

    resultado.debug.push(`Procesando variable: ${varName}`);

    // Verificar si tiene atributo tabla="true"
    const esTabla = /tabla\s*=\s*["']true["']/i.test(attributes);

    if (esTabla) {
      resultado.debug.push(`${varName} es una tabla`);

      // Procesar como tabla
      if (varContent.trim()) {
        // Buscar la tabla dentro del contenido
        const tableMatch = varContent.match(/<table[^>]*>([\s\S]*?)<\/table>/i);

        if (tableMatch) {
          const tableHTML = tableMatch[1];
          resultado.debug.push(`Tabla encontrada en ${varName}`);

          const tablaData = {
            nombre: varName,
            columnas: [],
            datos: [],
            total_filas: 0
          };

          // Buscar filas de la tabla (puede tener thead/tbody o solo tr directamente)
          let filas = [];

          // Primero intentar con tbody
          const tbodyMatch = tableHTML.match(/<tbody[^>]*>([\s\S]*?)<\/tbody>/i);
          if (tbodyMatch) {
            filas = [...tbodyMatch[1].matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)];
            resultado.debug.push(`Filas encontradas en tbody: ${filas.length}`);
          } else {
            // Si no hay tbody, buscar tr directamente
            filas = [...tableHTML.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)];
            resultado.debug.push(`Filas encontradas directamente: ${filas.length}`);
          }

          if (filas.length > 0) {
            // La primera fila son los headers
            const headerRow = filas[0];
            const headerCells = [...headerRow[1].matchAll(/<t[dh][^>]*>([\s\S]*?)<\/t[dh]>/gi)];

            const columnKeys = [];

            headerCells.forEach((cell, idx) => {
              const headerText = cell[1].replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
              let key = headerText.toLowerCase()
                .replace(/[áàäâ]/g, 'a')
                .replace(/[éèëê]/g, 'e')
                .replace(/[íìïî]/g, 'i')
                .replace(/[óòöô]/g, 'o')
                .replace(/[úùüû]/g, 'u')
                .replace(/ñ/g, 'n')
                .replace(/\s+/g, '_')
                .replace(/[^a-z0-9_]/g, '');

              if (!key) key = `col_${idx + 1}`;

              columnKeys.push(key);
              tablaData.columnas.push({
                indice: idx,
                nombre: headerText,
                key: key
              });
            });

            resultado.debug.push(`Columnas procesadas: ${columnKeys.length}`);

            // Procesar filas de datos (saltear la primera que son headers)
            for (let i = 1; i < filas.length; i++) {
              const row = filas[i];
              const cells = [...row[1].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)];

              if (cells.length > 0) {
                const rowData = {};

                cells.forEach((cell, cellIdx) => {
                  const key = columnKeys[cellIdx] || `col_${cellIdx + 1}`;
                  const cellContent = cell[1];

                  // Limpiar el contenido de la celda pero preservar HTML estructural
                  const contenidoLimpio = limpiarElemento(cellContent);

                  rowData[key] = contenidoLimpio;
                });

                tablaData.datos.push(rowData);
              }
            }

            tablaData.total_filas = tablaData.datos.length;
            resultado.tablas.push(tablaData);
            resultado.debug.push(`Tabla ${varName} procesada: ${tablaData.total_filas} filas de datos`);
          }
        } else {
          resultado.debug.push(`${varName} marcada como tabla pero sin contenido <table>`);
          // Agregar tabla vacía
          resultado.tablas.push({
            nombre: varName,
            columnas: [],
            datos: [],
            total_filas: 0
          });
        }
      } else {
        resultado.debug.push(`${varName} es tabla pero está vacía`);
        // Agregar tabla vacía
        resultado.tablas.push({
          nombre: varName,
          columnas: [],
          datos: [],
          total_filas: 0
        });
      }

    } else {
      // Variable simple - limpiar contenido pero preservar HTML
      const contenidoLimpio = limpiarElemento(varContent);

      // Si después de limpiar no queda HTML significativo, extraer solo texto
      const soloTexto = contenidoLimpio.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

      if (contenidoLimpio === soloTexto || contenidoLimpio.length < soloTexto.length * 1.2) {
        resultado.variables[varName] = soloTexto;
      } else {
        resultado.variables[varName] = contenidoLimpio;
      }

      resultado.debug.push(`Variable ${varName} procesada`);
    }
  }

} catch (error) {
  resultado.debug.push(`Error: ${error.message}`);
}

// Resultado final
return [{
  json: {
    variables: resultado.variables,
    tablas: resultado.tablas,
    resumen: {
      variables_extraidas: Object.keys(resultado.variables).length,
      tablas_extraidas: resultado.tablas.length,
      fecha_procesamiento: new Date().toISOString()
    },
    debug: resultado.debug
  }
}];

